-- SCOM faction tarmacs: source art with native structure/decal ownership 1.0.1
-- data.lua supplies the reviewed allowlist before this source is composed.
local policies = assert(SCO_FactionTarmacPolicies, "Missing SCOM tarmac policy")
local prefabs = {}
local initialized = false
local installed = setmetatable({}, { __mode = "k" })
local layerFields = { "albedoDecalPath", "normalDecalPath" }

-- Sanctuary Import exports the module environment, ignoring chunk return values.
function Initialize()
    if initialized then return end
    assert(policies.schemaVersion == 1 and type(policies.units) == "table",
        "Unsupported SCOM tarmac policy")
    local paths, seen = {}, {}
    for targetId, policy in pairs(policies.units) do
        assert(policy.targetId == targetId and #policy.profiles > 0,
            "Invalid SCOM tarmac target " .. tostring(targetId))
        for _, profile in ipairs(policy.profiles) do
            assert(profile.width > 0 and profile.width < math.huge
                and profile.length > 0 and profile.length < math.huge
                and #profile.orientations > 0, "Invalid SCOM tarmac dimensions")
            for _, field in ipairs(layerFields) do
                local path = profile[field]
                assert(type(path) == "string" and path:match("%.sandecal$"),
                    "Invalid SCOM tarmac decal path")
                if not seen[path] then
                    seen[path] = true
                    paths[#paths + 1] = path
                end
            end
        end
    end
    table.sort(paths)
    local loader = Import("common/loading/decalTemplateLoader.lua")
    for _, path in ipairs(paths) do
        prefabs[path] = assert(loader.CreateDecalPrefab(path),
            "Could not create SCOM tarmac prefab " .. path)
    end
    initialized = true
end

local function ResolvePolicy(unit)
    local tp = unit.tp
    local general = tp and tp.general
    local policy = general and policies.units[general.tpId]
    if not policy or unit.tpId ~= policy.targetId then return end
    local class = general.class
    if type(class) ~= "table" or class[1] ~= policy.expectedClass[1]
        or class[2] ~= policy.expectedClass[2] then return end
    local model = general.modelTpId or general.tpId
    if model ~= policy.expectedModelTpId then return end

    -- Earlier source owners use several provenance shapes. Validate every
    -- available identity field without fabricating a field those owners lack.
    local source = tp.additions and tp.additions.faSourceContract
    if source ~= nil and type(source) ~= "table" then return end
    if source then
        if source.targetId and source.targetId ~= policy.targetId then return end
        if source.sourceId and source.sourceId ~= policy.sourceId then return end
        if source.sourceBlueprint and source.sourceBlueprint ~= policy.sourceBlueprint then return end
        if source.sourceBlueprintSha256 then
            if type(source.sourceBlueprintSha256) ~= "string"
                or string.lower(source.sourceBlueprintSha256) ~= string.lower(policy.sourceBlueprintSha256) then
                return
            end
        end
    end
    return policy
end

-- Structures and wrecks keep the same self.tarmac field. Each child remains a
-- native Decal, including its own fade thread and idempotent Delete method.
local function Composite(layers)
    local owner = { layers = layers, deleted = false }
    local function Each(self, method, ...)
        if self.deleted then return end
        for _, layer in ipairs(self.layers) do
            if not layer.deleted then layer[method](layer, ...) end
        end
    end
    function owner:SetEnabled(enabled) Each(self, "SetEnabled", enabled) end
    function owner:SetLifeTime(seconds) Each(self, "SetLifeTime", seconds) end
    function owner:SetPosition(position) Each(self, "SetPosition", position) end
    function owner:SetOpacity(opacity) Each(self, "SetOpacity", opacity) end
    function owner:GetEnabled()
        return not self.deleted and not self.layers[1].deleted
            and self.layers[1]:GetEnabled()
    end
    function owner:GetPosition() return self.layers[1]:GetPosition() end
    function owner:GetOpacity() return self.layers[1]:GetOpacity() end
    function owner:Delete()
        Each(self, "Delete")
        self.deleted = true
    end
    return owner
end

local function CreateTarmac(unit)
    local policy = ResolvePolicy(unit)
    if not policy or unit.tarmac then return end
    local placement = Import("common/systems/placementUtils.lua")
    local domains = Import("common/layers.lua").PlacementDomain
    if placement.GetPlacementDomain(unit.tp) == domains.Water then return end
    local position = unit:GetSimPosition()
    local status, hasWater = Engine.HasWater()
    if status == EngineErrorCode.Success and hasWater then
        local levelStatus, level = Engine.GetWaterLevel()
        if levelStatus == EngineErrorCode.Success then
            local heightStatus, height = Engine.SampleTerrainHeight(position)
            if heightStatus ~= EngineErrorCode.Success or height < level then return end
        end
    end
    assert(initialized, "SCOM tarmac prefabs were not initialized")

    -- Source variations are cosmetic. Stable instance identity avoids consuming
    -- either simulation's RNG or making registration depend on visibility order.
    local id = unit.id or {}
    local seed = (id.index or 0) + (id.version or 0)
    local profile = policy.profiles[seed % #policy.profiles + 1]
    local rotation = profile.orientations[seed % #profile.orientations + 1]
    local layers = {}
    local ok, message = pcall(function()
        for _, field in ipairs(layerFields) do
            local path = profile[field]
            local layer = assert(unit:CreateDecal(prefabs[path], profile.width, profile.length, rotation),
                "Could not instantiate SCOM tarmac layer " .. path)
            layers[#layers + 1] = layer
        end
    end)
    if not ok then
        for _, layer in ipairs(layers) do layer:Delete() end
        error(message, 0)
    end
    unit.tarmac = Composite(layers)
    unit.tarmac:SetEnabled(false)
end

function Install(clientUnit)
    if installed[clientUnit] then return end
    installed[clientUnit] = true
    local previousInit = clientUnit.__init
    function clientUnit:__init(...)
        previousInit(self, ...)
        -- Native Structure.__init next calls this virtual instance method.
        -- It also replaces the old Aeon no-op and Cybran donor-art overrides.
        if ResolvePolicy(self) then self.CreateTarmac = CreateTarmac end
    end
end

Policies = policies
